def detect(text: str) -> dict:
    """Слой A. Возвращает {hit, matched, category} — то же поле red_flag, что и в
    живой ноде доктора."""
    matched = [label for label, pattern in RED_FLAGS if pattern.search(text)]
    hit = bool(matched)
    category = "emergency"
    if hit:
        is_suicide = any("суицидальные" in m for m in matched)
        if len(matched) == 1 and is_suicide:
            category = "crisis"
        elif is_suicide:
            category = "emergency"  # суицид + что-то ещё -> ведём как emergency
    return {"hit": hit, "matched": matched, "category": category}


